            def double_number(match):
                num = float(match.group())
                return str(num * 2)
            processed[key] = re.sub(r'-?\d+\.?\d*', double_number, value)
        else:
            processed[key] = value
    try:
        df = pd.DataFrame([processed])
        return df
    except Exception:
        return pd.DataFrame()

